def transform(grid):
    """Duplicate the outermost rows and columns once."""
    rows = []
    for r, row in enumerate(grid):
        expanded = []
        for c, value in enumerate(row):
            expanded.extend([value] * (2 if c == 0 or c == len(row) - 1 else 1))
        rows.extend([expanded] * (2 if r == 0 or r == len(grid) - 1 else 1))
    return rows
